def get_pattern_prime(val):
    """Pattern for prime values (like 7 and 3)"""
    return [[val, 0, val], [0, 0, 0], [val, 0, val]]

def get_pattern_composite(val):
    """Pattern for composite values (like 6)"""
    return [[val, val, 0], [val, 0, val], [0, val, val]]

def get_pattern(val):
    if val == 0:
        return [[0, 0, 0], [0, 0, 0], [0, 0, 0]]
    elif is_prime(val):
        return get_pattern_prime(val)
    else:
        return get_pattern_composite(val)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

